package com.tripmateai.controller; import com.tripmateai.dto.request.packing.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.packing.*; import com.tripmateai.service.PackingService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/trips/{tripId}/packing") @RequiredArgsConstructor public class PackingController {private final PackingService service; @GetMapping public ResponseEntity<ApiResponse<PackingChecklistResponse>> get(@PathVariable Long tripId){return ResponseUtils.success(service.get(tripId),"Packing checklist retrieved");} @PostMapping public ResponseEntity<ApiResponse<PackingItemResponse>> add(@PathVariable Long tripId,@Valid @RequestBody CreatePackingItemRequest r){return ResponseUtils.created(service.add(tripId,r),"Packing item added");} @PutMapping("/{itemId}") public ResponseEntity<ApiResponse<PackingItemResponse>> update(@PathVariable Long tripId,@PathVariable Long itemId,@Valid @RequestBody UpdatePackingItemRequest r){return ResponseUtils.success(service.update(tripId,itemId,r),"Packing item updated");} @PatchMapping("/{itemId}/toggle") public ResponseEntity<ApiResponse<PackingItemResponse>> toggle(@PathVariable Long tripId,@PathVariable Long itemId){return ResponseUtils.success(service.toggle(tripId,itemId),"Packing item toggled");} @DeleteMapping("/{itemId}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long tripId,@PathVariable Long itemId){service.delete(tripId,itemId);return ResponseUtils.success(null,"Packing item deleted");} @PostMapping("/generate") public ResponseEntity<ApiResponse<PackingChecklistResponse>> generate(@PathVariable Long tripId,@Valid @RequestBody GeneratePackingRequest r){return ResponseUtils.success(service.generate(tripId,r),"Packing suggestions generated");}}
